/**
 * Slack Socket Mode via `@slack/socket-mode`.
 *
 * Thin wrapper: ACK envelopes immediately, then forward Events API
 * payloads to the channel pack. Reconnect is handled by the SDK.
 */
import { LogLevel, SocketModeClient } from "@slack/socket-mode";
import { SLACK_LOG_PREFIX } from "../../internal/distribution.js";
function createBridgeLogger(write) {
    let level = LogLevel.INFO;
    const rank = {
        [LogLevel.ERROR]: 0,
        [LogLevel.WARN]: 1,
        [LogLevel.INFO]: 2,
        [LogLevel.DEBUG]: 3,
    };
    const emit = (msgLevel, msgs) => {
        if (rank[msgLevel] > rank[level]) {
            return;
        }
        const text = msgs.map((m) => (typeof m === "string" ? m : JSON.stringify(m))).join(" ");
        write(`${SLACK_LOG_PREFIX} Socket Mode ${text}`);
    };
    return {
        debug: (...msgs) => emit(LogLevel.DEBUG, msgs),
        info: (...msgs) => emit(LogLevel.INFO, msgs),
        warn: (...msgs) => emit(LogLevel.WARN, msgs),
        error: (...msgs) => emit(LogLevel.ERROR, msgs),
        setLevel(next) {
            level = next;
        },
        getLevel: () => level,
        setName() {
            // Name is unused; Agent SDK prefixes lines itself.
        },
    };
}
function invokeHandler(log, label, handler, payload) {
    try {
        const result = handler(payload);
        if (result !== undefined && typeof result.then === "function") {
            void Promise.resolve(result).catch((error) => {
                log(`${SLACK_LOG_PREFIX} Socket Mode ${label} failed: ${errorMessage(error)}`);
            });
        }
    }
    catch (error) {
        log(`${SLACK_LOG_PREFIX} Socket Mode ${label} failed: ${errorMessage(error)}`);
    }
}
function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}
/**
 * Start a Socket Mode connection. Call `stop()` to tear down.
 * Resolves once the first WebSocket session is connected.
 */
export async function startSlackSocketMode(options) {
    const write = options.logger ?? ((line) => console.log(line));
    const client = new SocketModeClient({
        appToken: options.appToken,
        logger: createBridgeLogger(write),
        logLevel: LogLevel.INFO,
        autoReconnectEnabled: true,
    });
    client.on("connected", () => {
        write(`${SLACK_LOG_PREFIX} Socket Mode connected`);
    });
    client.on("reconnecting", () => {
        write(`${SLACK_LOG_PREFIX} Socket Mode reconnecting`);
    });
    client.on("disconnected", () => {
        write(`${SLACK_LOG_PREFIX} Socket Mode disconnected`);
    });
    client.on("slack_event", (evt) => {
        // ACK immediately (3s envelope budget); then dispatch off-path.
        void Promise.resolve(evt.ack()).catch((error) => {
            write(`${SLACK_LOG_PREFIX} Socket Mode ACK failed: ${errorMessage(error)}`);
        });
        if (evt.type === "events_api") {
            if (evt.body !== undefined) {
                invokeHandler(write, "onEvent", options.onEvent, evt.body);
            }
            return;
        }
        if (evt.type === "interactive") {
            if (evt.body !== undefined && options.onInteractive !== undefined) {
                invokeHandler(write, "onInteractive", options.onInteractive, evt.body);
            }
            return;
        }
    });
    await client.start();
    return {
        async stop() {
            await client.disconnect();
            write(`${SLACK_LOG_PREFIX} Socket Mode stopped`);
        },
    };
}
